#!/usr/bin/env python3
"""Generate the credits entries that come from data, and check that nothing is missing (UI-213).

The credits screen (docs/dev/credits.md) is built from `credit` objects in data/credits/*.pd:

  * data/credits/credits.pd     written by hand: authors, the National Library of Russia, notes;
  * data/credits/generated.pd   GENERATED by this script from
        - data-sources/geodata.manifest.json: every source with attribution.required = true,
        - assets/LICENSES.csv: every row with attribution_required = yes,
    except those a hand-written entry already covers (`source = "<manifest id>"` or
    `asset = "<path>"` in credits.pd, which lets an entry show the credit in its own words).

Checks (--check, run in CI and by ctest):
  1. generated.pd is exactly what this script generates now;
  2. every manifest source with attribution.required has an entry (generated or hand-written);
  3. every registry row with attribution_required = yes has an entry;
  4. a hand-written `source` / `asset` refers to something that exists;
  5. a hand-written entry for a source with attribution.required shows the manifest's attribution text
     (the Russian text of its name or text key contains it), so a credit cannot silently change.

Usage:
    python tools/gen_credits.py            # rewrite data/credits/generated.pd
    python tools/gen_credits.py --check    # exit 1 if it is out of date or a credit is missing
"""

from __future__ import annotations

import argparse
import csv
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
LANGUAGE = "ru"

GENERATED_HEADER = """format_version = 1

# GENERATED by tools/gen_credits.py - do not edit by hand (python tools/gen_credits.py rewrites it).
# Credits that come from data (UI-213, docs/dev/credits.md): every source of
# data-sources/geodata.manifest.json with attribution.required = true and every row of
# assets/LICENSES.csv with attribution_required = yes, unless data/credits/credits.pd covers it with a
# hand-written entry (source = "<manifest id>" / asset = "<path>"). Names and attribution texts are
# copied verbatim: they are the legal wording of the providers and are not translated.
"""


class Credit:
    """A `credit` object as far as this script needs it."""

    def __init__(self, entry_id: str, fields: dict[str, str]):
        self.id = entry_id
        self.fields = fields


# ---------------------------------------------------------------------------------------------------
# .pd helpers (only what the credits files use: top-level `credit "id" { key = value ... }` blocks)


def pd_quote(text: str) -> str:
    out = text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\t", "\\t")
    return f'"{out}"'


def pd_unquote(text: str) -> str:
    result = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == "\\" and i + 1 < len(text):
            nxt = text[i + 1]
            result.append({"n": "\n", "t": "\t", "r": "\r"}.get(nxt, nxt))
            i += 2
        else:
            result.append(c)
            i += 1
    return "".join(result)


STRING = r'"((?:[^"\\\n]|\\.)*)"'
FIELD = re.compile(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(?:" + STRING + r"|([A-Za-z0-9_.\-]+))", re.MULTILINE)
HEADER = re.compile(r"\bcredit\s+(?:" + STRING + r"|([A-Za-z_][A-Za-z0-9_]*))\s*\{")


def strip_comments(text: str) -> str:
    """Removes `#` comments outside strings, keeping the line structure."""
    lines = []
    for line in text.splitlines():
        in_string = False
        escaped = False
        cut = len(line)
        for i, c in enumerate(line):
            if in_string:
                if escaped:
                    escaped = False
                elif c == "\\":
                    escaped = True
                elif c == '"':
                    in_string = False
            elif c == '"':
                in_string = True
            elif c == "#":
                cut = i
                break
        lines.append(line[:cut])
    return "\n".join(lines)


def parse_credits(text: str) -> list[Credit]:
    text = strip_comments(text)
    credits = []
    pos = 0
    while True:
        match = HEADER.search(text, pos)
        if match is None:
            return credits
        entry_id = pd_unquote(match.group(1)) if match.group(1) is not None else match.group(2)
        depth = 1
        i = match.end()
        in_string = False
        while i < len(text) and depth > 0:
            c = text[i]
            if in_string:
                if c == "\\":
                    i += 1
                elif c == '"':
                    in_string = False
            elif c == '"':
                in_string = True
            elif c == "{":
                depth += 1
            elif c == "}":
                depth -= 1
            i += 1
        body = text[match.end() : i - 1]
        fields = {}
        for field in FIELD.finditer(body):
            value = pd_unquote(field.group(2)) if field.group(2) is not None else field.group(3)
            fields[field.group(1)] = value
        credits.append(Credit(entry_id, fields))
        pos = i


def parse_loc(text: str) -> dict[str, str]:
    """`key = "text"` lines of a string table."""
    table = {}
    for match in re.finditer(r"^([A-Za-z0-9_.]+)\s*=\s*" + STRING + r"\s*$", strip_comments(text), re.MULTILINE):
        table[match.group(1)] = pd_unquote(match.group(2))
    return table


# ---------------------------------------------------------------------------------------------------
# Inputs


def load_manifest(root: Path) -> list[dict]:
    path = root / "data-sources" / "geodata.manifest.json"
    return json.loads(path.read_text(encoding="utf-8"))["sources"]


def load_assets(root: Path) -> list[dict]:
    path = root / "assets" / "LICENSES.csv"
    with path.open(encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle))


def load_loc(root: Path) -> dict[str, str]:
    table: dict[str, str] = {}
    directory = root / "data" / "loc" / LANGUAGE
    for path in sorted(directory.glob("*.pd")):
        table.update(parse_loc(path.read_text(encoding="utf-8")))
    return table


def read_credits(path: Path) -> list[Credit]:
    return parse_credits(path.read_text(encoding="utf-8")) if path.is_file() else []


def slug(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", text.lower()).strip("_")


def source_requires_attribution(source: dict) -> bool:
    return bool((source.get("attribution") or {}).get("required"))


def asset_requires_attribution(row: dict) -> bool:
    return (row.get("attribution_required") or "").strip().lower() not in ("", "no")


# ---------------------------------------------------------------------------------------------------
# Generation


def generate(manifest: list[dict], assets: list[dict], handwritten: list[Credit]) -> str:
    covered_sources = {c.fields["source"] for c in handwritten if "source" in c.fields}
    covered_assets = {c.fields["asset"] for c in handwritten if "asset" in c.fields}
    blocks = []

    for index, source in enumerate(manifest):
        if not source_requires_attribution(source) or source["id"] in covered_sources:
            continue
        lines = [
            f'credit {pd_quote("source_" + slug(source["id"]))} {{',
            "    section = data",
            f"    order = {100 + 10 * index}",
            f'    source = {pd_quote(source["id"])}',
            f'    name = {pd_quote(source["name"])}',
        ]
        if source.get("provider"):
            lines.append(f'    provider = {pd_quote(source["provider"])}')
        if source.get("license"):
            lines.append(f'    license = {pd_quote(source["license"])}')
        text = (source.get("attribution") or {}).get("text")
        if text:
            lines.append(f"    text = {pd_quote(text)}")
        lines.append("}")
        blocks.append("\n".join(lines))

    for index, row in enumerate(assets):
        if not asset_requires_attribution(row) or row["path"] in covered_assets:
            continue
        lines = [
            f'credit {pd_quote("asset_" + slug(row["path"]))} {{',
            "    section = assets",
            f"    order = {100 + 10 * index}",
            f'    asset = {pd_quote(row["path"])}',
            f'    name = {pd_quote(row["title"] or row["path"])}',
        ]
        if row.get("author"):
            lines.append(f'    provider = {pd_quote(row["author"])}')
        if row.get("license"):
            lines.append(f'    license = {pd_quote(row["license"])}')
        lines.append("}")
        blocks.append("\n".join(lines))

    return GENERATED_HEADER + "".join("\n" + block + "\n" for block in blocks)


# ---------------------------------------------------------------------------------------------------
# Checks


def check(root: Path) -> list[str]:
    manifest = load_manifest(root)
    assets = load_assets(root)
    loc = load_loc(root)
    credits_dir = root / "data" / "credits"
    handwritten = read_credits(credits_dir / "credits.pd")
    generated_path = credits_dir / "generated.pd"
    errors = []

    expected = generate(manifest, assets, handwritten)
    actual = generated_path.read_text(encoding="utf-8") if generated_path.is_file() else None
    if actual is None or actual.replace("\r\n", "\n") != expected:
        errors.append(f"{generated_path.relative_to(root).as_posix()} is out of date: run python tools/gen_credits.py")

    entries = handwritten + read_credits(generated_path)
    covered_sources = {c.fields["source"] for c in entries if "source" in c.fields}
    covered_assets = {c.fields["asset"] for c in entries if "asset" in c.fields}
    by_id = {source["id"]: source for source in manifest}
    asset_paths = {row["path"] for row in assets}

    for source in manifest:
        if source_requires_attribution(source) and source["id"] not in covered_sources:
            errors.append(f"source '{source['id']}' requires attribution but has no credits entry")
    for row in assets:
        if asset_requires_attribution(row) and row["path"] not in covered_assets:
            errors.append(f"asset '{row['path']}' requires attribution but has no credits entry")

    for entry in handwritten:
        source_id = entry.fields.get("source")
        if source_id is not None:
            source = by_id.get(source_id)
            if source is None:
                errors.append(f"credit '{entry.id}': unknown source '{source_id}' (not in the geodata manifest)")
            elif source_requires_attribution(source):
                wanted = source["attribution"]["text"]
                shown = [
                    entry.fields.get("name", ""),
                    entry.fields.get("text", ""),
                    loc.get(entry.fields.get("name_key", ""), ""),
                    loc.get(entry.fields.get("text_key", ""), ""),
                ]
                if not any(wanted in text for text in shown):
                    errors.append(
                        f"credit '{entry.id}': must show the attribution text of '{source_id}' "
                        f"({wanted[:60]!r}) in its name or text"
                    )
        asset_path = entry.fields.get("asset")
        if asset_path is not None and asset_path not in asset_paths:
            errors.append(f"credit '{entry.id}': unknown asset '{asset_path}' (not in assets/LICENSES.csv)")
        for field in ("name_key", "text_key"):
            key = entry.fields.get(field)
            if key is not None and key not in loc:
                errors.append(f"credit '{entry.id}': {field} '{key}' is not defined in data/loc/{LANGUAGE}")

    return errors


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--check", action="store_true", help="check instead of writing")
    parser.add_argument("--root", type=Path, default=ROOT, help="repository root (for tests)")
    args = parser.parse_args(argv)
    root: Path = args.root

    if args.check:
        errors = check(root)
        for error in errors:
            print(f"gen_credits: {error}", file=sys.stderr)
        if not errors:
            print("gen_credits: credits are complete and up to date")
        return 1 if errors else 0

    text = generate(
        load_manifest(root), load_assets(root), read_credits(root / "data" / "credits" / "credits.pd")
    )
    target = root / "data" / "credits" / "generated.pd"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding="utf-8", newline="\n")
    print(f"gen_credits: wrote {target.relative_to(root).as_posix()}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
